def has_path(graph, source, target):
    stack = [source]
    visited = {source}
    while stack:
        node = stack.pop()
        if node == target:
            return True
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                stack.append(neighbor)
    return False

